changeSet.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'clinlims' AND table_name = 'electronic_order'
            AND column_name = 'reject_reason'
    ) THEN
        ALTER TABLE clinlims.electronic_order RENAME COLUMN reject_reason TO rejection_author;
    ELSE
        ALTER TABLE clinlims.electronic_order ADD COLUMN rejection_author varchar(255);
    END IF;
END $$;
